from patch_rows p
where q.external_id = p.external_id;

do $$
declare
  keylogger_ok boolean;
  password_ok boolean;
  chart_ok boolean;
begin
  select public.answer_text_match_group('keylogger', autograde_rules_json -> 'gaps' -> 1 -> 'accepted_groups', 'phrase', 'exact') is not null
  into keylogger_ok
  from public.questions
  where external_id = 'cyberspace-network-security-and-data-transfer.practice_bank.topic_07_08_cyberspace_cloud.q020';

  if not coalesce(keylogger_ok, false) then
    raise exception 'Slash alias hotfix failed: keylogger is not accepted';
  end if;

  select public.answer_text_match_group('password protection', autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups', 'phrase', 'exact') is not null
    and public.answer_text_match_group('digital signature', autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups', 'phrase', 'exact') is not null
  into password_ok
  from public.questions
  where external_id = 'digital-data.practice_bank.topic_01_digital_data.q095';

  if not coalesce(password_ok, false) then
    raise exception 'Slash alias hotfix failed: PDF feature aliases are not accepted';
  end if;

  select public.answer_text_match_group('left justification', autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups', 'phrase', 'exact') is not null
    and public.answer_text_match_group('text alignment', autograde_rules_json -> 'gaps' -> 0 -> 'accepted_groups', 'phrase', 'exact') is not null
  into chart_ok
  from public.questions
  where external_id = 'digital-data.practice_bank.topic_01_digital_data.q094';

  if not coalesce(chart_ok, false) then
    raise exception 'Slash alias hotfix failed: RTF justification aliases are not accepted';
  end if;
end $$;

